    await post(`${path}/tasks`, { title: 'Original' });
    await post(`${path}/tasks`, { title: 'Second' });
    const taskPath = (await html(path)).match(/action="([^" ]+\/tasks\/[^" ]+)"/)[1];
    await post(taskPath, { completed: '1' });
